cat > lib/actions.sh <<'E'
#!/bin/bash
# Form actions: a form posts to its own page with the action named in the query (?action=name).
# The query key must be Function-URL safe (A-Z a-z 0-9 _ . -); "?/name" is rejected with 400 there.
action_url() { echo "?action=$1"; }
# Prints the action named by a query string, or nothing.
action_from_query() { case "$1" in action=*) echo "${1#action=}" ;; esac; }
E
cat > tests/forms_test.sh <<'E'
#!/bin/bash
fail=0
bash bin/render event | grep -q 'action="?action=save"' || { echo "render"; fail=1; }
# Query keys must match A-Z a-z 0-9 _ . - (the Function URL rejects others with 400)
for f in event seat refund; do
  bash bin/render $f | grep -o 'action="?[^"]*"' | sed 's/action="?//; s/"$//; s/=.*//' | grep -qv '^[A-Za-z0-9_.-]*$' && { echo "query-key $f"; fail=1; }
done
bash bin/handle POST '/events/1/edit?action=save' | grep -q '^200 save' || { echo "handle"; fail=1; }
exit $fail
E
sed -i 's|`?/<操作名>`|`?action=<操作名>`（キーに `/` は使えない。Function URL が 400 を返す）|' docs/framework.md
bash scripts/verify.sh; echo rc=$?; git stash -q; bash -c 'true'; git stash pop -q
git add -A; git commit -qm "EVT-412: use ?action=<name> for form actions (Function URL rejects '/' in query keys)

